function localizeDatePretty(date, useMonthAbbreviations = true, isMidSentence = false) {
    const locale = getCurrentLocale();
    if (!(date instanceof Date)) {
        return '';
    }
    const now = new Date();
    const tomorrow = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
    const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
    if (now.getDate() === date.getDate() &&
        now.getMonth() === date.getMonth() &&
        now.getFullYear() === date.getFullYear()) {
        return isMidSentence ? translate('global|today') : translate('global|Today');
    }
    else if (tomorrow.getDate() === date.getDate() &&
        tomorrow.getMonth() === date.getMonth() &&
        tomorrow.getFullYear() === date.getFullYear()) {
        return isMidSentence ? translate('global|tomorrow') : translate('global|Tomorrow');
    }
    else if (yesterday.getDate() === date.getDate() &&
        yesterday.getMonth() === date.getMonth() &&
        yesterday.getFullYear() === date.getFullYear()) {
        return isMidSentence ? translate('global|yesterday') : translate('global|Yesterday');
    }
    let dateString;
    const dateFormat = locale.DATETIME_FORMATS.mediumDate.toLowerCase();
    const startType = dateFormat.charAt(0); //'y' | 'm' | 'd'
    const endType = dateFormat.charAt(dateFormat.length - 1);
    const useYear = now.getFullYear() !== date.getFullYear();
    let month;
    const day = date.getDate();
    const year = date.getFullYear();
    if (useMonthAbbreviations) {
        month = locale.DATETIME_FORMATS.SHORTMONTH[date.getMonth()];
    }
    else {
        month = locale.DATETIME_FORMATS.MONTH[date.getMonth()];
    }
    switch (startType) {
        case 'd':
            if (endType === 'y') {
                //d m y
                dateString = day + ' ' + month;
                if (useYear) {
                    dateString += ' ' + year;
                }
            }
            else {
                //d, y m
                if (useYear) {
                    dateString = day + ', ' + year + ' ' + month;
                }
                else {
                    dateString = day + ' ' + month;
                }
            }
            break;
        default:
        case 'm':
            if (endType === 'y') {
                //m d, y
                dateString = month + ' ' + day;
                if (useYear) {
                    dateString += ', ' + year;
                }
            }
            else {
                //m y, d
                if (useYear) {
                    dateString = month + ' ' + year + ', ' + day;
                }
                else {
                    dateString = month + ' ' + day;
                }
            }
            break;
        case 'y':
            if (useYear) {
                if (endType === 'm') {
                    //y, d m
                    dateString = year + ', ' + day + ' ' + month;
                }
                else {
                    //y m d
                    dateString = year + ' ' + month + ' ' + day;
                }
            }
            else {
                if (endType === 'm') {
                    //d m
                    dateString = day + ' ' + month;
                }
                else {
                    //m d
                    dateString = month + ' ' + day;
                }
            }
            break;
    }
    return dateString;
}
function localizeDate(d, mmDdOnly) {
    const locale = getCurrentLocale();
    if (d == null) {
        return '';
    }
    if (!isValidDateObject(d)) {
        return String(d);
    }
    const separatorMatch = locale.DATETIME_FORMATS.mediumDate.match(/[^A-Za-z]/);
    let separator = '/';
    if (separatorMatch != null) {
        separator = separatorMatch[0];
    }
    const patternPieces = locale.DATETIME_FORMATS.mediumDate.split(separator);
    const localizedStrings = [];
    for (let i = 0; i < 3; i++) {
        switch (patternPieces[i]) {
            case 'd':
                localizedStrings.push(d.getDate());
                break;
            case 'dd':
                localizedStrings.push(d.getDate());
                break;
            case 'M':
                localizedStrings.push(d.getMonth() + 1);
                break;
            case 'MM':
                localizedStrings.push(d.getMonth() + 1);
                break;
            case 'yy':
                if (mmDdOnly !== true) {
                    localizedStrings.push(d.getFullYear());
                }
                break;
            case 'yyyy':
                if (mmDdOnly !== true) {
                    localizedStrings.push(d.getFullYear());
                }
                break;
            default:
                console.error('Unexpected format while localizing date');
        }
    }
    return localizedStrings.join(separator);
}
