// The app nav can be either expanded or collapsed
// by default it is expanded
// on page refresh the app nav checks for 'neon-app-nav-is-expanded' in local storage
// if false it renders it collapsed
// This exported util is used BEFORE the app-nav is mounted and connected to allow for skeleton state consistency across manual refreshes/navigation
function maintainExpandedState() {
    const isExpandedLocalStorage = localStorage.getItem('neon-app-nav-is-expanded');
    switch (isExpandedLocalStorage) {
        case 'true':
            document.body.classList.remove('neon-ui-state-app-nav-collapsed');
            break;
        case 'false':
            document.body.classList.add('neon-ui-state-app-nav-collapsed');
            break;
        default:
            document.body.classList.remove('neon-ui-state-app-nav-collapsed');
            break;
    }
}
// Yes, we are setting this up so it will be called as soon as someone imports from '@ps-refarch-ux/neon'.
if (document.body != null) {
    maintainExpandedState();
}
else {
    document.addEventListener('DOMContentLoaded', maintainExpandedState);
}

